        move n3,x0                    ; mask (v12: fills the slot)
        move a0,r3
        abs a           a2,n7
        asl #2,a,a
        move a,y1                     ; |4 bp|, limited
        mpy y1,#13,a                  ; index (A1)
        tfr y1,b
        and x0,b        a1,r4
        asl #10,b,b                   ; interpolation fraction, Q23
        move (r4)+n4
        move x:(r4)+,x0 b,y0          ; T[i]
        move x:(r4),y1                ; T[i+1]
        mpy y0,y1,a
        mac -y0,x0,a    x0,b
        add b,a         n7,b
        asr #5,a,a                    ; (K/2) tanh = table / 32
        move n0,x0                    ; dt (v12: fills the slot)
        tst b           a1,a
        neg a ifmi
        move a1,y0
        mpy x0,y0,a     y0,r1
        asl a           r2,b
        move r5,b0
        add b,a         n1,x0
        move a0,r5
