        asl a           r2,b
        move r5,b0
        add b,a         n1,x0
        move a0,r5
        move a,r2
        mpy -x0,y0,a    r2,y1
        add x1,a
        sub y1,a        n0,x0
        move a,y1
        mpy x0,y1,a     r1,b
        asl a           r3,b0
        add b,a         y1,r6
        move n3,x0                    ; mask (v12: fills the slot)
        move a0,r3
        abs a           a2,n7
        asl #2,a,a
        move a,y1                     ; |4 bp|, limited
        mpy y1,#13,a                  ; index (A1)
        tfr y1,b
        and x0,b        a1,r4
        asl #10,b,b                   ; interpolation fraction, Q23
        move (r4)+n4
        move x:(r4)+,x0 b,y0          ; T[i]
        move x:(r4),y1                ; T[i+1]
        mpy y0,y1,a
        mac -y0,x0,a    x0,b
        add b,a         n7,b
        asr #5,a,a                    ; (K/2) tanh = table / 32
        move n0,x0                    ; dt (v12: fills the slot)
        tst b           a1,a
        neg a ifmi
        move a1,y0
        mpy x0,y0,a     y0,r1
        asl a           r2,b
        move r5,b0
        add b,a
        move a0,r5
        move a,r2
        move r6,a
        asl #5,a,a
        move x:$0,x0                  ; the next sample's ddt (v12)
        move a,y:(r7)+
 filt_hp_env_end:
        jmp filter_done
 filter_done:
        move y:$142,a                 ; R6 was the HP register: recompute state base
        lsl #6,a
        add #>$800,a
        move a1,r4
        nop
        move r1,y:(r4+$9)
        move r2,y:(r4+$a)
        move r3,y:(r4+$b)
        move r5,y:(r4+$c)
        move r6,y:(r4+$d)
; ---- Pass 4: VCA, one linear gain ramp per block (v10). R4 = state base.
VCA_STEP32 equ 6086976               ; 32 x VCA_SLEW: full scale in 1 ms, per block
; Target: the envelope level at the block end (+8 = 1), or for the gate (+8 >= 2)
; full scale while more than half a block of the gate count (+15) remains (the
; count drops by 32 per block). The change toward it is clamped to 32 slew steps
; (full scale in 1 ms) and spread as dg per sample (toward zero, so the ramp
; never overshoots); the block-end gain (+14) snaps to the target within 32 LSB.
; A block held at full scale skips the multiply: exact unity.
 vca_pass:
        move y:(r4+$8),a
        tst a
        jeq vca_off
        cmp #1,a
        jeq vca_env
        move y:(r4+$15),a             ; gate: samples still open
        clr b
        move #>$7fffff,y1
        cmp #16,a
        tgt y1,b                      ; open while more than half a block remains
        move #>32,x0
        sub x0,a
        tst a
        jge vca_count
        clr a
 vca_count:
        move a1,y:(r4+$15)
        tfr b,a
        jmp vca_target
 vca_env:
        move y:(r4+$f),a              ; envelope level at the block end
 vca_target:
        move a,y1                     ; target T
        move y:(r4+$14),b             ; gain g at the block start
        sub b,a
        move #>VCA_STEP32,x1
        cmp x1,a
        tgt x1,a
        move #>-VCA_STEP32,x1
        cmp x1,a
        tlt x1,a                      ; d = clamp(T - g, +-32 slew steps)
        tst a
        jge vca_up
        neg a
        asr #5,a,a
        move a1,a
        neg a
        jmp vca_step
 vca_up:
        asr #5,a,a
        move a1,a
 vca_step:
        move a1,x1                    ; dg = d/32, toward zero
        asl #5,a,a
        add b,a                       ; g + 32 dg
        move a1,x0
        move y1,a
        sub x0,a
        abs a
        cmp #32,a
        move x0,a
        tlt y1,a                      ; within 32 LSB of the target: snap to it
        move a1,y:(r4+$14)
        move x1,a
        tst a
        jne vca_ramp
        move #>$7fffff,x0
        cmp x0,b
        jeq vca_off                   ; held at full scale: exact unity
 vca_ramp:
        move y:$140,r5                ; output bank, linear (no reliance on M7 wrap)
        do #32,vca_end
        add x1,b        y:(r5),y0
        move b1,x0
        mpysu y0,x0,a                 ; y * g (unsigned gain)
        move a,y:(r5)+
 vca_end:
 vca_off:
        rts
silent:
        clr a
        do #32,silent_done
        move a,y:(r7)+
silent_done:
        rts
